"},{"event":"Billy Joel Monthly Residency","date":"2014","description":"Ongoing monthly performances setting attendance records","category":"performance"}]	[{"feature":"Suspended Ceiling Design","description":"Innovative cable-supported roof system providing unobstructed views","category":"architecture"},{"feature":"Center-Hung Sound System","description":"Advanced audio system designed for optimal sound distribution","category":"acoustics"},{"feature":"Multiple Configurations","description":"Versatile setup options for different types of events","category":"stage"},{"feature":"Location","description":"Situated directly above Penn Station with excellent transportation access","category":"location"}]	\N	\N
